```mermaid
classDiagram
    class Token {
        +str type
        +str value
        +__init__(type: str, value: str)
        +__repr__() str
    }
    class Node {
        <<abstract>>
    }
    class NumberNode {
        +Token token
        +__init__(token: Token)
    }
    class BinOpNode {
        +Node left
        +Token op
        +Node right
        +__init__(left: Node, op: Token, right: Node)
    }
    Node <|-- NumberNode
    Node <|-- BinOpNode
    BinOpNode --> Node : left
    BinOpNode --> Node : right
    class CalculatorError {
        +str message
        +__init__(message: str)
    }
    class TokenizationError {
        +__init__(message: str)
    }
    class ParsingError {
        +__init__(message: str)
    }
    class DivisionByZeroError {
        +__init__(message: str)
    }
    CalculatorError <|-- TokenizationError
    CalculatorError <|-- ParsingError
    CalculatorError <|-- DivisionByZeroError
    class Lexer {
        +str text
        +int pos
        +char current_char
        +__init__(text: str)
        +tokenize() List[Token]
        -advance()
        -skip_whitespace()
        -number() Token
    }
    class Parser {
        +List[Token] tokens
        +int pos
        +Token current_token
        +__init__(tokens: List[Token])
        +parse() Node
        -factor() Node
        -term() Node
        -expr() Node
        -eat(token_type: str)
    }
    class Evaluator {
        +__init__()
        +visit(node: Node) float
        -visit_NumberNode(node: NumberNode) float
        -visit_BinOpNode(node: BinOpNode) float
    }
    class Formatter {
        +__init__()
        +format_result(value: float) str
        +format_error(error: CalculatorError) str
    }
    class CalculatorApp {
        +__init__()
        +run()
        -process_expression(expression: str) str
    }
    CalculatorApp --> Lexer
    CalculatorApp --> Parser
    CalculatorApp --> Evaluator
    CalculatorApp --> Formatter
```

